import{_ as o,l as s,o as e,c as n,v as r,p as l,x as t,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"SRT 除法","description":"","frontmatter":{"title":"SRT 除法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/srt-division.md","filePath":"cs/srt-division.md","lastUpdated":1789023840000}'),E={name:"cs/srt-division.md"};function p(m,a,A,T,_,R){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="srt-除法" tabindex="-1">SRT 除法 <a class="header-anchor" href="#srt-除法" aria-label="Permalink to &quot;SRT 除法&quot;">​</a></h1><div class="epigraph"><p>商数字若允许冗余，就不必等余数的完整符号才决定这一位：用最高几位查表，每步可以切出两位甚至更多。</p><footer>—— 据 Robertson, A New Class of Digital Division Methods, IRE Trans. 1958；Ercegovac and Lang, Digital Arithmetic 整理</footer></div><p><a href="/cs/restoring-division">上一课</a>的恢复/不恢复每步只定 1 比特商，且试减往往要看完整余数符号。缺口是延迟：64 位除要几十拍，卡住整数单元。SRT（Sweeney–Robertson–Tocher）用<strong>冗余商数字</strong>和余数的高位近似，让每步切 \\(r\\) 位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不恢复除法已经允许中间余数为负，商比特仍是 \\(0/1\\)。若商数字取自 \\(\\{\\bar 1,0,1\\}\\) 或更宽（基-4 SRT 用 \\(\\{\\bar 2,\\ldots,2\\}\\)），同一数值可有多种表示，选择不必精确。缺口因此不是再写一遍移位减，而是：<strong>用余数与除数的最高若干比特查表</strong>，选出商数字 \\(q_i\\)，做 \\(R\\leftarrow rR - q_i D\\)，余数保持在可纠正的窗口内。</p><p>Pentium FDIV 的著名缺陷正是 SRT 表漏项——本课用它当边界警告，不写勘误表。</p><h3 id="冗余不是「商可以随便错」" tabindex="-1">冗余不是「商可以随便错」 <a class="header-anchor" href="#冗余不是「商可以随便错」" aria-label="Permalink to &quot;冗余不是「商可以随便错」&quot;">​</a></h3><p>冗余保证：近似选择之后，下一步还能把误差吸收。最后必须把冗余表示收成常规补码商（片上加一次校正）。把 SRT 理解成近似除法，整数 <code>div</code> 的精确性合同会破。IEEE 754 要求正确舍入的除法，硬件仍要精确商，只是中间数字冗余。</p><p><span class="marginnote">Robertson 1958；Tocher 同期独立。Intel 的基-4 SRT 实现见各种微结构文献；教材级叙述见 Ercegovac/Lang 与 Parhami, <em>Computer Arithmetic</em>。Harris 通常不把 SRT 表画完，本课只钉机制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定基 \\(r=2^k\\)。除数规格化到 \\([1/2,1)\\) 一类区间（整数除可先数前导零）。查表输入：余数高 \\(p\\) 位与除数高 \\(q\\) 位。输出 \\(q_i\\)。部分余数用 CSA 更新，避免每步 CLA——与<a href="/cs/wallace-carry-save">华莱士</a>同一压缩思想，用在迭代里。最后一次传播进位，若余数为负则商减 1 并加回除数。</p>',11)),(e(),l(h,null,{default:t(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RD%5B%22%E4%BD%99%E6%95%B0%E9%AB%98%E4%BD%8D%20%2B%20%E9%99%A4%E6%95%B0%E9%AB%98%E4%BD%8D%22%5D%20--%3E%20LUT%5B%22%E5%95%86%E6%95%B0%E5%AD%97%E8%A1%A8%22%5D%0A%20%20LUT%20--%3E%20UPD%5B%22rR%20-%20qD%EF%BC%88CSA%EF%BC%89%22%5D%0A%20%20UPD%20--%3E%20RD%0A%20%20UPD%20--%3E%20CORR%5B%22%E7%BB%93%E6%9D%9F%E6%A0%A1%E6%AD%A3%E4%B8%BA%E7%B2%BE%E7%A1%AE%E5%95%86%22%5D%0A%20%20CORR%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%89%9B%E9%A1%BF%E5%80%92%E6%95%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>基越高，每步位数越多，表越大、余数窗口越紧。Pentium 的表是基-4 的实现选择，不是 SRT 定义本身。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课牛顿迭代走乘法器求倒数，适合已有快速 <a href="/cs/fp-mul-fma">FMA</a> 的浮点通路；SRT 适合整数与浮点共用的移位–加单元。微处理器常：整数除 SRT 或恢复，浮点除 SRT 或 Goldschmidt。本课不把两种都画进同一框图。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给完整商选择表，不分析 Pentium FDIV 的具体漏项坐标。不引入 Goldschmidt 级数。也不把验证用的形式化除法证明写进来——那是<a href="/cs/proof-assistants">证明助手</a>另一课程已结束的技能，本课只做电路。</p><p>后课默认：SRT 用冗余商数字与短余数估计加速迭代除；最终校正后仍是精确商。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恢复/不恢复每步 1 比特；SRT 用冗余让每步切 \\(k\\) 位。</li><li>查表只看高位；CSA 更新部分余数；结束校正。</li><li>表不完整会错（FDIV）；语义仍是精确除。</li><li>出处：Robertson, <em>IRE Trans.</em>, 1958；Ercegovac and Lang；Parhami, <em>Computer Arithmetic</em>。</li></ul>',8))])}const B=o(E,[["render",p]]);export{u as __pageData,B as default};
